ALTER TABLE "wallpapers" ADD CONSTRAINT "wallpaper_stored_metadata" CHECK ("wallpapers"."upload_state" NOT IN ('stored', 'processing', 'completed') OR ("wallpapers"."file_type" IS NOT NULL AND "wallpapers"."mime_type" IS NOT NULL AND "wallpapers"."width" IS NOT NULL AND "wallpapers"."width" > 0 AND "wallpapers"."height" IS NOT NULL AND "wallpapers"."height" > 0 AND "wallpapers"."file_size_bytes" IS NOT NULL AND "wallpapers"."file_size_bytes" > 0 AND "wallpapers"."original_filename" IS NOT NULL));